CREATE SCHEMA control;
CREATE TABLE control.sla_policies (id uuid PRIMARY KEY, tenant_id text NOT NULL, code text NOT NULL, object_type text NOT NULL, version integer NOT NULL, state text NOT NULL DEFAULT 'ACTIVE', UNIQUE (tenant_id, code, version), CHECK (state IN ('DRAFT','ACTIVE','DISABLED')));
CREATE TABLE control.sla_targets (id uuid PRIMARY KEY, tenant_id text NOT NULL, sla_policy_id uuid NOT NULL REFERENCES control.sla_policies(id), name text NOT NULL, duration_minutes integer NOT NULL CHECK (duration_minutes > 0), start_condition text NOT NULL, stop_condition text NOT NULL);
CREATE TABLE control.sla_instances (id uuid PRIMARY KEY, tenant_id text NOT NULL, object_type text NOT NULL, object_id uuid NOT NULL, target_id uuid NOT NULL REFERENCES control.sla_targets(id), policy_version integer NOT NULL, state text NOT NULL DEFAULT 'RUNNING', started_at timestamptz NOT NULL, due_at timestamptz NOT NULL, paused_at timestamptz, completed_at timestamptz, version integer NOT NULL DEFAULT 1 CHECK (version > 0), UNIQUE (tenant_id, object_type, object_id, target_id), CHECK (state IN ('RUNNING','PAUSED','WARNING','CRITICAL','BREACHED','MET','CANCELLED')));
CREATE TABLE control.sla_events (id uuid PRIMARY KEY, tenant_id text NOT NULL, instance_id uuid NOT NULL REFERENCES control.sla_instances(id), event_type text NOT NULL, from_state text, to_state text, reason text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sla_instances_due ON control.sla_instances(tenant_id, state, due_at);
